<?php
declare(strict_types=1);
namespace App\Cms;
final class CmsBlockRendererRegistry { public const TYPES=['rich_text','hero','image_text','faq','cta']; public function template(string $type):string { if(!in_array($type,self::TYPES,true))throw new \InvalidArgumentException('Unknown CMS block type.'); return 'shop/cms/block/_'.$type.'.html.twig'; } public function validate(string $type,array $c):array { $errors=[]; $required=match($type){'rich_text'=>['content'],'hero'=>['headline'],'image_text'=>['text'],'faq'=>['items'],'cta'=>['headline','buttonLabel','buttonUrl'],default=>['__unsupported']}; foreach($required as $key)if(empty($c[$key]))$errors[]=$key.' is required.'; if(isset($c['buttonUrl'])&&!self::safeUrl((string)$c['buttonUrl']))$errors[]='buttonUrl is unsafe.'; if($type==='image_text'&&isset($c['imagePosition'])&&!in_array($c['imagePosition'],['left','right'],true))$errors[]='imagePosition is invalid.'; return $errors;} private static function safeUrl(string $u):bool{return str_starts_with($u,'/')&&!str_starts_with($u,'//')||(filter_var($u,FILTER_VALIDATE_URL)!==false&&in_array(parse_url($u,PHP_URL_SCHEME),['http','https'],true));} }
